<?php

namespace Tests\Feature\RentalAgreement;

use App\Mail\RentalAgreementSigned;
use App\Models\Pms\PmsRoom;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Mail;
use Illuminate\Support\Facades\Storage;
use Tests\TestCase;

class RentalAgreementSubmitFlowTest extends TestCase
{
    private int $propertyId;
    private int $bookingId;
    private string $consentText = 'I consent to the rental agreement (test fixture).';
    // 50x50 PNG generated by GD (known-good for the local libpng decoder)
    private const SIG_PNG = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAADIAAAAyCAIAAACRXR/mAAAACXBIWXMAAA7EAAAOxAGVKw4bAAAAYElEQVRYhe3XIQ6AQBAEwVvC/798WEIwrUBUuXFtZ/be63+OrwPeySpkFbIKWYWsQlYhq5BVyCpkFbKKn2adjz0zn3Sste5HerzqQFYhq5BVyCpkFbIKWYWsQlYhq5BVXPdpCV+FAdBJAAAAAElFTkSuQmCC';

    protected function setUp(): void
    {
        parent::setUp();

        $this->propertyId = DB::table('properties')->insertGetId([
            'name' => 'RA-Submit-Test ' . uniqid(),
            'seo_url' => 'ra-submit-test-' . uniqid(),
            'instant_booking_button' => 'Book Now',
            'standard_rate' => 200,
            'no_of_guest' => 4,
            'type' => 'condo',
            'status' => 'true',
            'rental_agreement_required' => 1,
        ]);

        $this->bookingId = DB::table('booking_requests')->insertGetId([
            'property_id' => $this->propertyId,
            'checkin' => '2026-06-01',
            'checkout' => '2026-06-04',
            'name' => 'Submit Guest',
            'email' => 'submit-guest@example.com',
            'mobile' => '+1-555-0100',
            'adults' => 2,
            'child' => 0,
            'total_pets' => 0,
            'total_night' => 3,
            'total_amount' => 600,
            'rental_aggrement_status' => 'false',
            'operation' => 'check-booking',
        ]);

        // Make sure signature directory exists where the controller writes
        @mkdir(public_path('uploads/signature'), 0755, true);
    }

    protected function tearDown(): void
    {
        // Clean up any PDF artifacts from this test booking
        $row = DB::table('booking_requests')->where('id', $this->bookingId)->first();
        if ($row && $row->rental_agreement_pdf_path) {
            Storage::disk('local')->delete($row->rental_agreement_pdf_path);
        }
        // Find PDFs by booking-id pattern (in case test ran multiple)
        $patternPath = 'agreements';
        if (Storage::disk('local')->exists($patternPath)) {
            foreach (Storage::disk('local')->files($patternPath) as $f) {
                if (str_contains($f, 'booking_' . $this->bookingId . '_')) {
                    Storage::disk('local')->delete($f);
                }
            }
        }

        DB::table('booking_requests')->where('id', $this->bookingId)->delete();
        DB::table('properties')->where('id', $this->propertyId)->delete();
        parent::tearDown();
    }

    private function validPayload(array $overrides = []): array
    {
        return array_merge([
            'booking_id'   => $this->bookingId,
            'signature'    => self::SIG_PNG,
            'consent'      => '1',
            'consent_text' => $this->consentText,
            'consent_hash' => hash_hmac('sha256', $this->consentText, config('app.key')),
        ], $overrides);
    }

    public function test_submit_saves_signature_audit_columns(): void
    {
        Mail::fake();
        $resp = $this->post('/rental-aggrement-data-save', $this->validPayload());
        $resp->assertRedirect();

        $b = DB::table('booking_requests')->where('id', $this->bookingId)->first();

        // New audit columns
        $this->assertNotNull($b->rental_agreement_signed_at);
        $this->assertNotNull($b->rental_agreement_signed_ip);
        $this->assertNotNull($b->rental_agreement_signed_user_agent);
        $this->assertSame($this->consentText, $b->rental_agreement_consent_text);

        // Legacy columns also populated
        $this->assertSame('true', $b->rental_aggrement_status);
        $this->assertNotNull($b->rentar_agreement_date);
        $this->assertNotNull($b->rentar_agreement_ip);
        $this->assertNotEmpty($b->rental_aggrement_signature);
    }

    public function test_submit_generates_pdf_and_stores_path(): void
    {
        Mail::fake();
        $this->post('/rental-aggrement-data-save', $this->validPayload());

        $b = DB::table('booking_requests')->where('id', $this->bookingId)->first();
        $this->assertNotEmpty($b->rental_agreement_pdf_path);
        $this->assertSame($b->rental_agreement_link, $b->rental_agreement_pdf_path,
            'Legacy rental_agreement_link should be repurposed to the new PDF path');
        $this->assertTrue(Storage::disk('local')->exists($b->rental_agreement_pdf_path));
    }

    public function test_submit_dispatches_emails_to_guest_and_admin(): void
    {
        Mail::fake();
        $this->post('/rental-aggrement-data-save', $this->validPayload());

        Mail::assertSent(RentalAgreementSigned::class, 2);
        Mail::assertSent(RentalAgreementSigned::class, function ($m) {
            return $m->audience === 'user' && $m->hasTo('submit-guest@example.com');
        });
        Mail::assertSent(RentalAgreementSigned::class, function ($m) {
            return $m->audience === 'admin';
        });
    }

    public function test_submit_rejects_when_consent_unchecked(): void
    {
        Mail::fake();
        $payload = $this->validPayload();
        unset($payload['consent']);

        $resp = $this->from('/booking/rental-aggrement/' . $this->bookingId)
                     ->post('/rental-aggrement-data-save', $payload);
        $resp->assertRedirect();
        $resp->assertSessionHas('danger');

        $b = DB::table('booking_requests')->where('id', $this->bookingId)->first();
        $this->assertSame('false', $b->rental_aggrement_status);
        $this->assertNull($b->rental_agreement_signed_at);
        Mail::assertNothingSent();
    }

    public function test_submit_rejects_when_consent_text_tampered(): void
    {
        Mail::fake();
        $payload = $this->validPayload([
            'consent_text' => 'I AGREE TO TAMPERED TERMS', // text changed but hash is for the original
        ]);

        $resp = $this->from('/booking/rental-aggrement/' . $this->bookingId)
                     ->post('/rental-aggrement-data-save', $payload);
        $resp->assertRedirect();
        $resp->assertSessionHas('danger');

        $b = DB::table('booking_requests')->where('id', $this->bookingId)->first();
        $this->assertSame('false', $b->rental_aggrement_status);
        Mail::assertNothingSent();
    }

    public function test_submit_is_idempotent_on_already_signed_booking(): void
    {
        Mail::fake();
        // Pre-mark as signed (no PDF yet — simulating legacy signing)
        DB::table('booking_requests')->where('id', $this->bookingId)->update([
            'rental_aggrement_status' => 'true',
        ]);
        $beforeFiles = Storage::disk('local')->exists('agreements')
            ? count(Storage::disk('local')->files('agreements'))
            : 0;

        $resp = $this->post('/rental-aggrement-data-save', $this->validPayload());
        $resp->assertRedirect(); // existing handler's else-branch

        $afterFiles = Storage::disk('local')->exists('agreements')
            ? count(Storage::disk('local')->files('agreements'))
            : 0;

        $this->assertSame($beforeFiles, $afterFiles, 'No new PDF should be written on a re-submit of an already-signed booking');
        Mail::assertNothingSent();
    }

    public function test_pms_booking_can_render_and_submit_website_managed_agreement(): void
    {
        Mail::fake();

        DB::table('basic_settings')->updateOrInsert(
            ['name' => 'rental_agreement_template_html'],
            ['value' => '<p>PMS agreement for {{guest_name}} at {{property_name}}</p>', 'created_at' => now(), 'updated_at' => now()]
        );

        $room = PmsRoom::create([
            'pms_property_id' => 'submit-pms-property',
            'pms_room_id' => 'submit-pms-room',
            'pms_source' => 'lodgify',
            'name' => 'Submit PMS Room',
            'seo_url' => 'submit-pms-room',
            'status' => 'true',
            'currency' => 'USD',
            'rental_agreement_required' => 1,
            'rental_agreement_signing_mode' => 'post_confirmation',
        ]);

        $bookingId = DB::table('booking_requests')->insertGetId([
            'property_id' => $room->id,
            'pms_source' => 'lodgify',
            'pms_room_id' => 'submit-pms-room',
            'checkin' => '2027-06-01',
            'checkout' => '2027-06-04',
            'name' => 'PMS Submit Guest',
            'email' => 'pms-submit-guest@example.test',
            'mobile' => '+1-555-0130',
            'adults' => 2,
            'child' => 0,
            'total_pets' => 0,
            'total_night' => 3,
            'total_amount' => 750,
            'rental_aggrement_status' => 'false',
            'booking_status' => 'booking-confirmed',
            'payment_status' => 'paid',
        ]);

        try {
            $this->get('/booking/' . $bookingId . '/sign-agreement')
                ->assertOk()
                ->assertSee('Submit PMS Room')
                ->assertSee('PMS agreement for PMS Submit Guest at Submit PMS Room');

            $consentText = 'I consent to the PMS rental agreement.';
            $response = $this->post('/rental-aggrement-data-save', [
                'booking_id' => $bookingId,
                'signature' => self::SIG_PNG,
                'consent' => '1',
                'consent_text' => $consentText,
                'consent_hash' => hash_hmac('sha256', $consentText, config('app.key')),
            ]);

            $response->assertRedirect('pms/payment/success/' . $bookingId);

            $booking = DB::table('booking_requests')->where('id', $bookingId)->first();
            $this->assertSame('true', $booking->rental_aggrement_status);
            $this->assertNotEmpty($booking->rental_agreement_pdf_path);
            $this->assertTrue(Storage::disk('local')->exists($booking->rental_agreement_pdf_path));

            Mail::assertSent(RentalAgreementSigned::class, 2);
        } finally {
            $booking = DB::table('booking_requests')->where('id', $bookingId)->first();
            if ($booking && $booking->rental_agreement_pdf_path) {
                Storage::disk('local')->delete($booking->rental_agreement_pdf_path);
            }
            DB::table('booking_requests')->where('id', $bookingId)->delete();
            DB::table('pms_rooms')->where('id', $room->id)->delete();
        }
    }
}
